                        (id, text, durationMs, mediaBitmap) -> {
                            if (renderer != null) {
                                renderer.showCommentary(text, durationMs, mediaBitmap);
                            }
                        },
                        track -> {
                            if (trackScheduler != null) {
                                videoRuntimePorts.retireManifestedVisualOwner();
                                videoRuntimePorts.retireLegacyVisualOwner();
